<template>
  <el-form label-position="top" :disabled="disabled" @submit.prevent>
    <template v-if="kind==='map'"><el-form-item label="MAP实际观察UTC"><el-input v-model="form.observed_at" aria-label="MAP实际观察UTC" /></el-form-item><quantity-field v-model="form.map" label="MAP" :units="['mm[Hg]']" /><el-form-item label="MAP原测量方式"><el-select v-model="form.measurement_method" aria-label="MAP原测量方式"><el-option v-for="(label,key) in methods" :key="key" :value="key" :label="label" /></el-select></el-form-item><el-input v-model="form.measurement_basis_note" aria-label="MAP原测量依据" type="textarea" maxlength="1000" placeholder="至少20字原测量依据，不从收缩压/舒张压推算" /></template>
    <template v-if="['respiratory_support','vasoactive'].includes(kind)"><el-form-item v-for="[key,label] in intervalFields" :key="key" :label="label"><el-input v-model="form[key]" :aria-label="label" :placeholder="key==='ended_at'?'未明确停止时保留空；停止时间须与核实止点相同':'明确原UTC时刻，不能自动补当前时间'" /></el-form-item><el-checkbox v-model="form.continuity_confirmed">原区间连续性已核实</el-checkbox><el-input v-if="form.continuity_confirmed" v-model="form.continuity_basis_note" aria-label="原区间连续性依据" type="textarea" maxlength="1000" placeholder="至少20字核实依据；离散记录不推为连续" /><p>已停止区间为[开始,停止)，未停止区间只核实至所填止点（含止点），不延长到当前。</p></template>
    <template v-if="kind==='respiratory_support'"><el-form-item label="原呼吸支持方式"><el-select v-model="form.delivery_mode" aria-label="原呼吸支持方式"><el-option v-for="(label,key) in deliveryModes" :key="key" :value="key" :label="label" /></el-select></el-form-item><el-input v-model="form.device_description" aria-label="原呼吸支持设备说明" maxlength="200" placeholder="可选原设备说明" /><p>明确无支持与未知分别保存；高流量、低流量不自动宣称满足SOFA呼吸支持。</p></template>
    <template v-if="kind==='arterial_pair'"><reference-picker v-model="selected.pao2" type="pao2" label="原PaO₂检验来源" v-bind="scope" /><reference-picker v-model="selected.fio2" type="fio2" label="原FiO₂点测来源" v-bind="scope" /><reference-picker v-model="selected.support" type="respiratory_support" label="原呼吸支持区间来源" v-bind="scope" /><el-checkbox v-model="form.arterial_sample_confirmed">已核实所选原样本为动脉血</el-checkbox><el-checkbox v-model="form.same_sampling_state_confirmed">已核实不同原时刻属于本次采样状态</el-checkbox><el-checkbox v-model="form.fio2_applicability_confirmed">已核实所选原FiO₂适用于本次采样</el-checkbox><el-input v-model="form.review_note" aria-label="动脉配对医生核实依据" type="textarea" maxlength="1000" placeholder="至少20字当前医生回顾依据，三个未确认项保留false" /><p>保留PaO₂采样与FiO₂实际观察两个时刻；不自动最近配对，不计算P/F比或宣称评分完整。当前回顾签署不能追认为旧截止时已知。</p></template>
    <template v-if="kind==='vasoactive'"><reference-picker v-model="selected.drug_mapping" type="mapping" label="明确已发布原药物映射" v-bind="scope" /><el-form-item v-for="[key,label] in streamFields" :key="key" :label="label"><el-input v-model="form.stream_identity[key]" :aria-label="label" :maxlength="key==='identity_basis_note'?1000:120" /></el-form-item><reference-picker v-model="selected.origin" type="origin" label="实际已给药eMAR原链（可选）" :mapping-id="selected.drug_mapping?.mapping_id||''" v-bind="scope" /><el-form-item label="实际剂量输入类型"><el-select v-model="form.mode" aria-label="实际剂量输入类型"><el-option label="直接按体重剂量 ug/kg/min" value="weight_normalized" /><el-option label="绝对给入速率" value="absolute" /><el-option label="原浓度与泵速" value="pump" /></el-select></el-form-item><template v-if="form.mode"><quantity-field v-if="form.mode!=='pump'" v-model="form.rate" label="原给入速率" :units="form.mode==='weight_normalized'?['ug/kg/min']:['ug/min','mg/h']" /><template v-else><quantity-field v-model="form.concentration" label="原配液浓度" :units="['ug/mL','mg/mL']" /><quantity-field v-model="form.pump_rate" label="原泵速" :units="['mL/h']" /></template><reference-picker v-model="selected.weight" type="weight" label="原体重点测（可选）" v-bind="scope" /><el-checkbox v-model="form.weight_applicability_confirmed">已核实原体重适用于本次给入区间</el-checkbox><el-input v-if="form.weight_applicability_confirmed" v-model="form.weight_basis_note" aria-label="给入原体重适用依据" type="textarea" maxlength="1000" placeholder="至少20字，不假设70kg或把直接ug/kg/min再次除体重" /></template><p>原已给药eMAR仅作来源链；其旧无时区时钟不能证明连续UTC区间。保留0、未知和实际单位，不换算去甲肾上腺素等效剂量。</p></template>
    <template v-if="kind==='infection_episode'"><el-form-item label="医生感染核实状态"><el-select v-model="form.infection_status" aria-label="医生感染核实状态"><el-option v-for="(label,key) in infectionStates" :key="key" :value="key" :label="label" /></el-select></el-form-item><el-form-item v-for="[key,label] in infectionClocks" :key="key" :label="label"><el-input v-model="form[key]" :aria-label="label" placeholder="明确原UTC；可选时刻留空保留未知" /></el-form-item><el-input v-model="form.onset_basis_note" aria-label="感染发生UTC依据" type="textarea" maxlength="1000" placeholder="至少20字，未知发生时间须说明；不默认正常基线" /><el-input v-model="form.infection_basis_note" aria-label="医生感染核实依据" type="textarea" maxlength="1000" placeholder="至少20字当前医生核实依据，感染不等于脓毒症或急性器官归因" /><reference-picker v-model="selected.evidence_lab" type="evidence_lab_source" label="感染原检验证据（可选）" v-bind="scope" /><reference-picker v-model="selected.evidence_diagnosis" type="evidence_diagnosis_review" label="感染原诊断审核证据（可选）" v-bind="scope" /><el-button @click="addEvidence">添加明确原证据</el-button><p v-for="(item,index) in evidence" :key="`${item.kind}:${item.source_id}`">{{ item.kind }} · {{ item.source_id }} · {{ item.expected_content_hash }} <el-button @click="evidence.splice(index,1)">移除此原证据</el-button></p><p>所有状态均由实际医生当前签署。原发生时刻未知时保留null，不将当前回顾时刻写作发生或旧时已知；不自动诊断脓毒症。</p></template>
    <el-form-item label="原资料备注"><el-input v-model="form.note" aria-label="器官支持原资料备注" type="textarea" maxlength="1000" /></el-form-item>
    <p v-if="validationError" role="status">{{ validationError }}</p>
  </el-form>
</template>
<script setup>
import { computed, reactive, ref, watch } from "vue";
import { supportPayloadValid, supportUtc } from "@/api/inpatientSupport";
import ReferencePicker from "./ReferencePicker.vue";
import QuantityField from "./QuantityField.vue";
const props=defineProps({kind:{type:String,required:true},patientId:{type:Number,required:true},admissionId:{type:String,required:true},active:{type:Boolean,default:true},disabled:{type:Boolean,default:false}}),emit=defineEmits(["validity"]);
const quantity=unit=>({value:"",unit,absent_reason:""}),blank=()=>({observed_at:"",map:quantity("mm[Hg]"),measurement_method:"",measurement_basis_note:"",start_at:"",verified_until_at:"",ended_at:"",continuity_confirmed:false,continuity_basis_note:"",delivery_mode:"",device_description:"",arterial_sample_confirmed:false,same_sampling_state_confirmed:false,fio2_applicability_confirmed:false,review_note:"",stream_identity:{source_namespace:"",external_stream_id:"",identity_basis_note:""},mode:"",rate:quantity(""),concentration:quantity(""),pump_rate:quantity("mL/h"),weight_applicability_confirmed:false,weight_basis_note:"",infection_status:"",clinical_scope_start_at:"",clinical_scope_end_at:"",first_suspected_at:"",onset_at:"",onset_basis_note:"",infection_basis_note:"",note:""});
const form=ref(blank()),selected=reactive({pao2:null,fio2:null,support:null,drug_mapping:null,origin:null,weight:null,evidence_lab:null,evidence_diagnosis:null}),evidence=ref([]),scope=computed(()=>({patientId:props.patientId,admissionId:props.admissionId,active:props.active}));
const intervalFields=[["start_at","原区间开始UTC"],["verified_until_at","原区间已核实止点UTC"],["ended_at","明确停止UTC（可选）"]],streamFields=[["source_namespace","原给入流命名空间"],["external_stream_id","原给入流明确标识"],["identity_basis_note","原给入流身份依据"]],infectionClocks=[["clinical_scope_start_at","感染核实范围开始UTC"],["clinical_scope_end_at","感染核实范围结束UTC（可选）"],["first_suspected_at","首次怀疑UTC（可选）"],["onset_at","明确感染发生UTC（可选）"]];
const methods={invasive_arterial:"有创动脉原测量",oscillometric_device:"示波设备原测量",unknown:"原方式未知"},deliveryModes={none:"明确无呼吸支持",invasive_mechanical:"有创机械通气",noninvasive_positive_pressure:"无创正压支持",high_flow_nasal:"高流量鼻导管",low_flow_oxygen:"低流量氧疗",other:"其他原支持",unknown:"原支持未知"},infectionStates={suspected:"怀疑感染",documented:"记录已证实感染",not_suspected:"医生明确未怀疑感染",unknown:"感染情况未知"};
const refOf=(row,key)=>{if(!row)throw new Error("须明确选择完整原来源");return {[key]:row[key],expected_content_hash:row.content_hash};},q=value=>({value:value.value===""?null:value.value,unit:value.unit,absent_reason:value.absent_reason||null}),utc=value=>value===""?null:supportUtc(value);
function build(){const f=form.value;let p={note:f.note};if(props.kind==="map")p={...p,observed_at:supportUtc(f.observed_at),map:q(f.map),measurement_method:f.measurement_method,measurement_basis_note:f.measurement_basis_note};
if(["respiratory_support","vasoactive"].includes(props.kind))p={...p,start_at:supportUtc(f.start_at),verified_until_at:supportUtc(f.verified_until_at),ended_at:utc(f.ended_at),continuity_confirmed:f.continuity_confirmed,continuity_basis_note:f.continuity_confirmed?f.continuity_basis_note:null};
if(props.kind==="respiratory_support")p={...p,delivery_mode:f.delivery_mode,device_description:f.device_description||null};
if(props.kind==="arterial_pair")p={...p,pao2:refOf(selected.pao2,"lab_source_id"),fio2:refOf(selected.fio2,"observation_id"),support:refOf(selected.support,"support_source_id"),arterial_sample_confirmed:f.arterial_sample_confirmed,same_sampling_state_confirmed:f.same_sampling_state_confirmed,fio2_applicability_confirmed:f.fio2_applicability_confirmed,review_note:f.review_note};
if(props.kind==="vasoactive"){const shared={mode:f.mode,weight_ref:selected.weight?refOf(selected.weight,"observation_id"):null,weight_applicability_confirmed:f.weight_applicability_confirmed,weight_basis_note:f.weight_applicability_confirmed?f.weight_basis_note:null},dose=f.mode==="pump"?{...shared,concentration:q(f.concentration),pump_rate:q(f.pump_rate)}:{...shared,rate:q(f.rate)};p={...p,drug_mapping:refOf(selected.drug_mapping,"mapping_id"),stream_identity:{...f.stream_identity},origin:selected.origin?refOf(selected.origin,"administration_id"):null,dose_input:dose};}
if(props.kind==="infection_episode")p={...p,infection_status:f.infection_status,clinical_scope_start_at:supportUtc(f.clinical_scope_start_at),clinical_scope_end_at:utc(f.clinical_scope_end_at),first_suspected_at:utc(f.first_suspected_at),onset_at:utc(f.onset_at),onset_time_basis:f.onset_at?"explicit_clinician_verified_utc":"unknown",onset_basis_note:f.onset_basis_note,infection_basis_note:f.infection_basis_note,evidence_refs:evidence.value.map(item=>({...item}))};
if(props.kind==="vasoactive"&&!selected.drug_mapping.allowed_rate_units.includes(p.dose_input.mode==="pump"?p.dose_input.pump_rate.unit:p.dose_input.rate.unit))throw new Error("所选原药物映射尚未审核此实际速率单位，不能自动换算");
if(!supportPayloadValid(props.kind,p))throw new Error("请补齐本类型原量、缺测原因、原UTC、明确关联与核实依据；未知、0和未确认分别保留");return p;}
const validationError=computed(()=>{try{build();return "";}catch(failure){return failure.message;}});
function addEvidence(){for(const [key,kind] of [["evidence_lab","lab_source"],["evidence_diagnosis","diagnosis_review"]]){const row=selected[key];if(!row)continue;const ref=row.evidence_reference;if(ref&&ref.kind===kind&&evidence.value.length<16&&!evidence.value.some(item=>item.kind===kind&&item.source_id===ref.source_id))evidence.value.push({...ref});selected[key]=null;}}
function reset(){form.value=blank();Object.keys(selected).forEach(key=>selected[key]=null);evidence.value=[];}
watch(()=>form.value.mode,mode=>{form.value.rate=quantity(mode==="weight_normalized"?"ug/kg/min":"");form.value.concentration=quantity("");form.value.pump_rate=quantity("mL/h");});watch(()=>selected.drug_mapping?.mapping_id,()=>{selected.origin=null;});watch(validationError,error=>emit("validity",error===""),{immediate:true});defineExpose({build,reset});
</script>
<style scoped>.el-select{width:100%}.el-checkbox{display:block;height:auto;white-space:normal;margin:12px 0}p{line-height:1.7;overflow-wrap:anywhere}</style>
